import{_ as s,o as n,c as t,aN as m}from"./chunks/framework.D31DlcCL.js";const p="/img/cryptarithmetic-puzzle.svg",g=JSON.parse('{"title":"奥数精讲：数字谜（填空格的艺术）","description":"探索数字谜的奥秘，学习如何通过竖式特征、进位退位逻辑以及数项分析来破解隐藏在字母和空格下的数字。","frontmatter":{"title":"奥数精讲：数字谜（填空格的艺术）","date":"2026-02-28T10:00:00.000Z","categories":["数学"],"tags":["数字谜","竖式计算","逻辑推理"],"description":"探索数字谜的奥秘，学习如何通过竖式特征、进位退位逻辑以及数项分析来破解隐藏在字母和空格下的数字。"},"headers":[],"relativePath":"posts/primary-math-olympiad-cryptarithmetic-2.md","filePath":"posts/primary-math-olympiad-cryptarithmetic-2.md","lastUpdated":null}'),e={name:"posts/primary-math-olympiad-cryptarithmetic-2.md"};function l(i,a,r,o,c,h){return n(),t("div",null,[...a[0]||(a[0]=[m(`<h1 id="数字谜-数学里的-侦探游戏" tabindex="-1">数字谜：数学里的“侦探游戏” <a class="header-anchor" href="#数字谜-数学里的-侦探游戏" aria-label="Permalink to &quot;数字谜：数学里的“侦探游戏”&quot;">​</a></h1><p>数字谜（也称虫食算）是奥数中非常经典的一类题型。它要求我们在缺失了部分数字的竖式中，填入正确的数字，使算式成立。这不仅考验计算能力，更考验逻辑推理能力。</p><h2 id="一、-核心解题策略-找突破口" tabindex="-1">一、 核心解题策略：找突破口 <a class="header-anchor" href="#一、-核心解题策略-找突破口" aria-label="Permalink to &quot;一、 核心解题策略：找突破口&quot;">​</a></h2><p>解决数字谜的关键在于找到“突破口”。常见的突破口包括：</p><ol><li><strong>个位的运算：</strong> 是否有进位或退位？</li><li><strong>最高位的特征：</strong> 两个数相加，最高位进位只能是 1。</li><li><strong>特殊数字：</strong> 0 和 5 在乘法竖式中非常有辨识度。</li></ol><h3 id="【示例-1】加法竖式数字谜" tabindex="-1">【示例 1】加法竖式数字谜 <a class="header-anchor" href="#【示例-1】加法竖式数字谜" aria-label="Permalink to &quot;【示例 1】加法竖式数字谜&quot;">​</a></h3><p><strong>题目：</strong> 在下面的算式中，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span></span></span></span> 和 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span> 各代表什么数字？</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    A 5</span></span>
<span class="line"><span>  + 3 B</span></span>
<span class="line"><span>  -------</span></span>
<span class="line"><span>    8 2</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><h4 id="方法一-逻辑推理法-图示分析" tabindex="-1">方法一：逻辑推理法（图示分析） <a class="header-anchor" href="#方法一-逻辑推理法-图示分析" aria-label="Permalink to &quot;方法一：逻辑推理法（图示分析）&quot;">​</a></h4><p>通过观察竖式，我们可以分步骤进行推理：</p><p><img src="`+p+`" alt="数字谜逻辑分析图"></p><p><strong>推理步骤：</strong></p><ol><li><strong>看个位：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>+</mo><mi>B</mi></mrow><annotation encoding="application/x-tex">5 + B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span> 的结果尾数是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn></mrow><annotation encoding="application/x-tex">2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span></span></span></span>。因为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn></mrow><annotation encoding="application/x-tex">5</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span></span></span></span> 加上任何一位数最大是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>+</mo><mn>9</mn><mo>=</mo><mn>1</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">5+9=14</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">9</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">4</span></span></span></span>，所以 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mo>+</mo><mi>B</mi></mrow><annotation encoding="application/x-tex">5+B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span> 只能等于 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>。 <ul><li>得到：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi><mo>=</mo><mn>1</mn><mn>2</mn><mo>−</mo><mn>5</mn><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">B = 12 - 5 = 7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">5</span><span class="mrel">=</span><span class="mord mathrm">7</span></span></span></span>。</li><li>同时记住：个位向十位<strong>进 1</strong>。</li></ul></li><li><strong>看十位：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>+</mo><mn>3</mn><mo>+</mo></mrow><annotation encoding="application/x-tex">A + 3 +</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mbin">+</span></span></span></span> (进位的 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>1</mn></mrow><annotation encoding="application/x-tex">1</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">1</span></span></span></span>) <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">= 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.64444em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span>。 <ul><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>+</mo><mn>4</mn><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">A + 4 = 8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span>。</li><li>得到：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>=</mo><mn>4</mn></mrow><annotation encoding="application/x-tex">A = 4</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mrel">=</span><span class="mord mathrm">4</span></span></span></span>。</li></ul></li><li><strong>验证：</strong> <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>4</mn><mn>5</mn><mo>+</mo><mn>3</mn><mn>7</mn><mo>=</mo><mn>8</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">45 + 37 = 82</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">4</span><span class="mord mathrm">5</span><span class="mbin">+</span><span class="mord mathrm">3</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">8</span><span class="mord mathrm">2</span></span></span></span>。算式成立！</li></ol><h4 id="方法二-末尾分析法" tabindex="-1">方法二：末尾分析法 <a class="header-anchor" href="#方法二-末尾分析法" aria-label="Permalink to &quot;方法二：末尾分析法&quot;">​</a></h4><p>直接列出可能的组合。对于 5+B = \\dots 2，只有 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">B=7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mrel">=</span><span class="mord mathrm">7</span></span></span></span> 一种可能。这种方法在更复杂的题目中（如乘法）非常有效。</p><hr><h2 id="二、-引导性思考-如何解决复杂的数字谜" tabindex="-1">二、 引导性思考：如何解决复杂的数字谜？ <a class="header-anchor" href="#二、-引导性思考-如何解决复杂的数字谜" aria-label="Permalink to &quot;二、 引导性思考：如何解决复杂的数字谜？&quot;">​</a></h2><p>当你面对一个有很多空格的复杂竖式时，可以尝试以下思路：</p><ol><li><strong>列出范围：</strong> 比如两个三位数相加，和如果是四位数，那千位一定是 1。</li><li><strong>排除法：</strong> 如果某个空格乘以 5 得到尾数 0，那这个空格可能是双数。</li><li><strong>从易到难：</strong> 先填能确定的位，再推导剩下的。</li></ol><hr><h2 id="三、-引申思考-数字与字母的对应关系" tabindex="-1">三、 引申思考：数字与字母的对应关系 <a class="header-anchor" href="#三、-引申思考-数字与字母的对应关系" aria-label="Permalink to &quot;三、 引申思考：数字与字母的对应关系&quot;">​</a></h2><p>在更高级的数字谜中，相同的字母必须代表相同的数字，不同的字母代表不同的数字。 <strong>思考题：</strong> 如果 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mi>A</mi><mo>+</mo><mi>A</mi><mi>A</mi><mo>=</mo><mi>B</mi><mi>B</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">AA + AA = BBC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathit">A</span><span class="mord mathit">A</span><span class="mrel">=</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span>，你能推算出 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo separator="true">,</mo><mi>B</mi><mo separator="true">,</mo><mi>C</mi></mrow><annotation encoding="application/x-tex">A, B, C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8777699999999999em;vertical-align:-0.19444em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mpunct">,</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span> 吗？</p><ul><li>提示：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>+</mo><mi>A</mi></mrow><annotation encoding="application/x-tex">A+A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathit">A</span></span></span></span> 进位，说明 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span></span></span></span> 至少是 5。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi><mi>B</mi><mi>C</mi></mrow><annotation encoding="application/x-tex">BBC</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span> 是三位数，说明 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi></mrow><annotation encoding="application/x-tex">B</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span></span></span></span> 一定是 1。</li></ul><hr><h2 id="四、-举一反三-实战练习" tabindex="-1">四、 举一反三：实战练习 <a class="header-anchor" href="#四、-举一反三-实战练习" aria-label="Permalink to &quot;四、 举一反三：实战练习&quot;">​</a></h2><p>请尝试破解以下数字谜：</p><ol><li><p><strong>基础练习：</strong> 填入空格使等式成立。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    7 □</span></span>
<span class="line"><span>  - □ 4</span></span>
<span class="line"><span>  -------</span></span>
<span class="line"><span>    3 8</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></li><li><p><strong>进阶练习：</strong> 相同的汉字代表相同的数字。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    我 爱</span></span>
<span class="line"><span>  + 我 爱</span></span>
<span class="line"><span>  -------</span></span>
<span class="line"><span>  数 学 课</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p><em>提示：由于“我爱” + “我爱”变成了三位数，“数”一定是 1。</em></p></li><li><p><strong>挑战练习：</strong> 乘法竖式谜。</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    2 A</span></span>
<span class="line"><span>  ×   3</span></span>
<span class="line"><span>  -------</span></span>
<span class="line"><span>    B 1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div></li></ol><hr><p><strong>解析预览：</strong></p><ol><li>个位：10+□ - 4 = 8 (退位)，或者理解为 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mo>+</mo><mn>4</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">8+4=12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mbin">+</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>，所以个位是 2。十位被借走 1 剩下 6，6-□=3，所以十位是 3。结果：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>7</mn><mn>2</mn><mo>−</mo><mn>3</mn><mn>4</mn><mo>=</mo><mn>3</mn><mn>8</mn></mrow><annotation encoding="application/x-tex">72 - 34 = 38</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">7</span><span class="mord mathrm">2</span><span class="mbin">−</span><span class="mord mathrm">3</span><span class="mord mathrm">4</span><span class="mrel">=</span><span class="mord mathrm">3</span><span class="mord mathrm">8</span></span></span></span>。</li><li>“数”=1，“我”=5，“爱”=0 ... 不行，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>5</mn><mn>0</mn><mo>+</mo><mn>5</mn><mn>0</mn><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">50+50=100</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mbin">+</span><span class="mord mathrm">5</span><span class="mord mathrm">0</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span></span></span></span>，学和爱冲突。试试“爱”=2，“我”=6，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mn>2</mn><mo>+</mo><mn>6</mn><mn>2</mn><mo>=</mo><mn>1</mn><mn>2</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">62+62=124</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mord mathrm">2</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mord mathrm">2</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span><span class="mord mathrm">4</span></span></span></span>。学=2，也冲突。试试“爱”=7，“我”=8 ... <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>8</mn><mn>7</mn><mo>+</mo><mn>8</mn><mn>7</mn><mo>=</mo><mn>1</mn><mn>7</mn><mn>4</mn></mrow><annotation encoding="application/x-tex">87+87=174</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">8</span><span class="mord mathrm">7</span><span class="mbin">+</span><span class="mord mathrm">8</span><span class="mord mathrm">7</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">7</span><span class="mord mathrm">4</span></span></span></span>。数=1，学=7，爱=7 ... 冲突。 正确解：<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>+</mo><mi>A</mi></mrow><annotation encoding="application/x-tex">A+A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathit">A</span></span></span></span> 尾数是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi></mrow><annotation encoding="application/x-tex">A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span></span></span></span> 吗？不对，是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>+</mo><mi>A</mi></mrow><annotation encoding="application/x-tex">A+A</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathit">A</span></span></span></span> 尾数是 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>C</mi></mrow><annotation encoding="application/x-tex">C</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span></span></span></span>。且 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>+</mo><mi>A</mi><mo>≥</mo><mn>1</mn><mn>0</mn></mrow><annotation encoding="application/x-tex">A+A \\ge 10</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.8193em;vertical-align:-0.13597em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathit">A</span><span class="mrel">≥</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span></span></span></span>。 如果 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>=</mo><mn>6</mn></mrow><annotation encoding="application/x-tex">A=6</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mrel">=</span><span class="mord mathrm">6</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>+</mo><mn>6</mn><mo>=</mo><mn>1</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">6+6=12</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">2</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>C</mi><mo>=</mo><mn>2</mn></mrow><annotation encoding="application/x-tex">C=2</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.07153em;">C</span><span class="mrel">=</span><span class="mord mathrm">2</span></span></span></span>。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mo>+</mo><mn>6</mn><mo>+</mo><mn>1</mn><mo>=</mo><mn>1</mn><mn>3</mn></mrow><annotation encoding="application/x-tex">6+6+1=13</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">3</span></span></span></span>，<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi><mo>=</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">B=3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mrel">=</span><span class="mord mathrm">3</span></span></span></span>。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>6</mn><mn>6</mn><mo>+</mo><mn>6</mn><mn>6</mn><mo>=</mo><mn>1</mn><mn>3</mn><mn>2</mn></mrow><annotation encoding="application/x-tex">66+66=132</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">6</span><span class="mord mathrm">6</span><span class="mbin">+</span><span class="mord mathrm">6</span><span class="mord mathrm">6</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">3</span><span class="mord mathrm">2</span></span></span></span>。数=1, 学=3, 爱=6, 我=6。 (本题“我爱”相同，所以 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mo>×</mo><mo>(</mo><mn>1</mn><mn>0</mn><mi>A</mi><mo>+</mo><mi>B</mi><mo>)</mo><mo>=</mo><mn>1</mn><mn>0</mn><mn>0</mn><mi>S</mi><mo>+</mo><mn>1</mn><mn>0</mn><mi>X</mi><mo>+</mo><mi>K</mi></mrow><annotation encoding="application/x-tex">2 \\times (10A+B) = 100S + 10X + K</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.75em;"></span><span class="strut bottom" style="height:1em;vertical-align:-0.25em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mbin">×</span><span class="mopen">(</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathit">A</span><span class="mbin">+</span><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mclose">)</span><span class="mrel">=</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathrm">0</span><span class="mord mathit" style="margin-right:0.05764em;">S</span><span class="mbin">+</span><span class="mord mathrm">1</span><span class="mord mathrm">0</span><span class="mord mathit" style="margin-right:0.07847em;">X</span><span class="mbin">+</span><span class="mord mathit" style="margin-right:0.07153em;">K</span></span></span></span>)。</li><li><span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>×</mo><mn>3</mn></mrow><annotation encoding="application/x-tex">A \\times 3</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.76666em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mbin">×</span><span class="mord mathrm">3</span></span></span></span> 尾数是 1，只有 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>A</mi><mo>=</mo><mn>7</mn></mrow><annotation encoding="application/x-tex">A=7</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit">A</span><span class="mrel">=</span><span class="mord mathrm">7</span></span></span></span>。<span class="katex"><span class="katex-mathml"><math><semantics><mrow><mn>2</mn><mn>7</mn><mo>×</mo><mn>3</mn><mo>=</mo><mn>8</mn><mn>1</mn></mrow><annotation encoding="application/x-tex">27 \\times 3 = 81</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.64444em;"></span><span class="strut bottom" style="height:0.72777em;vertical-align:-0.08333em;"></span><span class="base textstyle uncramped"><span class="mord mathrm">2</span><span class="mord mathrm">7</span><span class="mbin">×</span><span class="mord mathrm">3</span><span class="mrel">=</span><span class="mord mathrm">8</span><span class="mord mathrm">1</span></span></span></span>，所以 <span class="katex"><span class="katex-mathml"><math><semantics><mrow><mi>B</mi><mo>=</mo><mn>8</mn></mrow><annotation encoding="application/x-tex">B=8</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="strut" style="height:0.68333em;"></span><span class="strut bottom" style="height:0.68333em;vertical-align:0em;"></span><span class="base textstyle uncramped"><span class="mord mathit" style="margin-right:0.05017em;">B</span><span class="mrel">=</span><span class="mord mathrm">8</span></span></span></span>。</li></ol>`,30)])])}const x=s(e,[["render",l]]);export{g as __pageData,x as default};
